// ---- hqsj helpers (batched triangles; everything merged per colour spec) ----
const HPI = Math.PI;
const hqR = () => LMCTX.rng();
const hqB = () => new Map();
function hqP(B, col){ const k = typeof col === 'string' ? col : JSON.stringify(col); let e = B.get(k); if (!e){ e = {col, p:[]}; B.set(k, e); } return e.p; }
function hqFlush(g, B){ for (const e of B.values()) if (e.p.length) LTris(g, e.p, e.col); }
const hqQ = (p, a, b, c, d) => { p.push(a[0], a[1], a[2], b[0], b[1], b[2], c[0], c[1], c[2], a[0], a[1], a[2], c[0], c[1], c[2], d[0], d[1], d[2]); };
function hqSA(r){ let s = 0; for (let i = 0; i < r.length; i++){ const a = r[i], b = r[(i + 1) % r.length]; s += a[0]*b[1] - b[0]*a[1]; } return s/2; }
const hqCCW = r => hqSA(r) < 0 ? r.slice().reverse() : r.slice();
function hqOff(r, d){   // r with positive hqSA; d > 0 grows outward (mitred, clamped)
  const n = r.length, o = [];
  for (let i = 0; i < n; i++){
    const p = r[(i + n - 1) % n], c = r[i], q = r[(i + 1) % n];
    let ax = c[0] - p[0], az = c[1] - p[1]; const la = Math.hypot(ax, az) || 1; ax /= la; az /= la;
    let bx = q[0] - c[0], bz = q[1] - c[1]; const lb = Math.hypot(bx, bz) || 1; bx /= lb; bz /= lb;
    let mx = az + bz, mz = -ax - bx; const ml = Math.hypot(mx, mz);
    if (ml < 1e-6){ mx = az; mz = -ax; } else { mx /= ml; mz /= ml; }
    const cs = Math.max(0.4, mx*az - mz*ax);
    o.push([c[0] + mx*d/cs, c[1] + mz*d/cs]);
  }
  return o;
}
function hqIn(r, x, z){ let c = false; for (let i = 0, j = r.length - 1; i < r.length; j = i++){ const a = r[i], b = r[j]; if ((a[1] > z) !== (b[1] > z) && x < (b[0] - a[0])*(z - a[1])/(b[1] - a[1]) + a[0]) c = !c; } return c; }
