        // Site 4 (Buildings 1-19): 3-4 storeys, steel frame with stucco cladding and ribbon windows; Site 5 (20-24): 3 storeys, curtain wall + aluminium panels
        const fl = s5 ? 3 : (b.h < 15 ? 3 : 4), fh = Math.max(3.9, Math.min(4.9, (b.h - 1.4)/fl));
        const H = s5 ? hqOffice(B, r, {fl, fh, g0:fh + 0.4, sp:1.0, wall:HQCIS.alu, glass:HQCIS.cw, mull:HQCIS.alu, ms:1.6, mw:0.18, md:0.25, roof:HQC.roof, par:1.3, bandOut:0.12})
                     : hqOffice(B, r, {fl, fh, g0:fh + 0.4, sp:1.65, wall:HQCIS.wall, glass:HQCIS.glass, mull:HQCIS.mull, ms:3.0, mw:0.25, md:0.15, roof:HQC.roof, par:1.3, bandOut:0.16});
        // glazed entrance atrium on the longest facade (full height, slightly proud) + roof plant screen
        let best = null; hqEdges(r, (a, c, L, ux, uz, nx, nz) => { if (!best || L > best.L) best = {a, c, L, ux, uz, nx, nz}; });
        if (best){ const m = [(best.a[0] + best.c[0])/2, (best.a[1] + best.c[1])/2], w = Math.min(16, best.L*0.3);
          const at = [[m[0] - best.ux*w/2, m[1] - best.uz*w/2], [m[0] + best.ux*w/2, m[1] + best.uz*w/2], [m[0] + best.ux*w/2 + best.nx*4, m[1] + best.uz*w/2 + best.nz*4], [m[0] - best.ux*w/2 + best.nx*4, m[1] - best.uz*w/2 + best.nz*4]];
          hqOffice(B, at, {fl:1, fh:H + 2.5, g0:H + 2.5, sp:0.2, wall:HQCIS.mull, glass:HQCIS.atr, mull:HQCIS.mull, ms:1.6, mw:0.12, md:0.12, roof:HQC.roof, par:0.4});
          // entrance canopy on two posts in front of the atrium, and a drop-off plaza
          const ry = Math.atan2(-best.uz, best.ux), cc = [m[0] + best.nx*9, m[1] + best.nz*9];
          hqBox(hqP(B, HQCIS.mull), cc[0], 4.3, cc[1], w + 4, 0.45, 10, ry);
          for (const s of [-1, 1]) hqBox(hqP(B, HQCIS.mull), cc[0] + best.ux*s*(w/2 + 1) + best.nx*3, 0, cc[1] + best.uz*s*(w/2 + 1) + best.nz*3, 0.5, 4.3, 0.5, ry);
          hqPatch(hqP(B, HQC.pave), hqRect(cc[0], cc[1], w + 10, 12, ry), 0.12, 0.4); }
