      const R = inset ? hqOff(ring, -inset) : ring, Hh = hqOff(hole, inset ? -0 : 0);
      const H = hqOffice(B, R, {y0, fl:nfl, fh:4.6, g0:4.6, sp:1.0, wall:white, glass, mull:white, ms:1.5, mw:0.2, md:0.5, par:1.0, base:false, noCap:true, bandOut:0.45});
